<template><view class="cottage"><view class="hero"><text class="eyebrow">MOOD COTTAGE</text><text class="title">心情互动小屋</text><text class="desc">给朋友下一场彩虹雨，或送一颗开心星</text></view><view class="scene" :class="moodClass"><view class="sun">✦</view><view class="cloud">☁</view><view class="house"><view class="window">{{ moodEmoji }}</view><view class="door"></view></view><view class="effect" v-if="effect==='rain'">🌈　💧　🌈　💧</view><view class="effect star" v-if="effect==='star'">✨　⭐　✨</view></view><view class="moods"><text class="label">今天的小屋天气</text><view class="mood-row"><view v-for="m in moods" :key="m.key" class="mood" :class="{selected:mood===m.key}" @click="mood=m.key">{{m.emoji}}<text>{{m.name}}</text></view></view></view><view class="gift-card"><text class="gift-title">送一份小心意</text><text class="gift-desc">演示版会在当前小屋播放动画，正式好友授权将在下一阶段接入</text><view class="gift-row"><view @click="play('rain')" class="gift">🌈<text>彩虹雨</text></view><view @click="play('star')" class="gift">⭐<text>开心星</text></view></view><text class="hint">{{hint}}</text></view></view></template>
<script>export default{data(){return{mood:'sunny',effect:'',hint:'点击礼物试试看',moods:[{key:'sunny',emoji:'☀️',name:'很开心'},{key:'cloudy',emoji:'⛅',name:'就这样'},{key:'rainy',emoji:'🌧️',name:'不高兴'}]}},computed:{moodClass(){return'mood-'+this.mood},moodEmoji(){return this.moods.find(x=>x.key===this.mood).emoji}},methods:{play(type){this.effect=type;this.hint=type==='rain'?'彩虹雨落下啦！':'开心星正在闪耀！';setTimeout(()=>{this.effect=''},3500)}}}</script>
<style lang="scss" scoped>.cottage{min-height:100vh;background:#f7f2ea;padding:60rpx 30rpx 140rpx;box-sizing:border-box}.hero{color:#493c49}.eyebrow{font-size:20rpx;letter-spacing:5rpx;color:#b58b8b}.title{display:block;font-size:48rpx;font-weight:700;margin-top:12rpx}.desc{display:block;color:#907f86;font-size:25rpx;margin-top:14rpx}.scene{height:500rpx;margin-top:30rpx;border-radius:34rpx;background:linear-gradient(#93d7f4,#dff5ff);position:relative;overflow:hidden;transition:.4s}.mood-cloudy{background:linear-gradient(#aab8cf,#e5e0df)}.mood-rainy{background:linear-gradient(#687f9f,#b6c5d4)}.sun{position:absolute;right:60rpx;top:50rpx;font-size:80rpx;color:#ffe88b}.cloud{position:absolute;left:50rpx;top:70rpx;font-size:110rpx;color:#fff8}.house{position:absolute;bottom:65rpx;left:50%;transform:translateX(-50%);width:300rpx;height:230rpx;background:#e5a77e;border-radius:20rpx 20rpx 8rpx 8rpx}.house:before{content:'';position:absolute;left:-35rpx;top:-100rpx;border-left:185rpx solid transparent;border-right:185rpx solid transparent;border-bottom:120rpx solid #bb6e68}.window{position:absolute;left:100rpx;top:65rpx;width:100rpx;height:80rpx;background:#bcecf3;border:10rpx solid #fff;text-align:center;line-height:60rpx;font-size:45rpx}.door{position:absolute;bottom:0;left:125rpx;width:55rpx;height:90rpx;background:#8e5e65;border-radius:30rpx 30rpx 0 0}.effect{position:absolute;left:30rpx;right:30rpx;top:210rpx;text-align:center;font-size:45rpx;animation:fall 3.5s linear}.star{animation:twinkle 1s ease-in-out infinite}.moods,.gift-card{background:#fff;border-radius:26rpx;padding:26rpx;margin-top:26rpx;box-shadow:0 10rpx 30rpx #8f716b12}.label,.gift-title{font-size:30rpx;font-weight:700;color:#4d4147}.mood-row,.gift-row{display:flex;justify-content:space-around;margin-top:22rpx}.mood,.gift{display:flex;flex-direction:column;align-items:center;color:#85747a;font-size:23rpx;gap:8rpx;padding:16rpx 22rpx;border-radius:20rpx}.mood{font-size:44rpx}.mood text,.gift text{font-size:22rpx}.mood.selected{background:#fff0c2}.gift{font-size:44rpx;background:#fff5e9;min-width:150rpx}.gift:nth-child(2){background:#f2edff}.gift-desc{display:block;color:#a09094;font-size:22rpx;margin-top:10rpx}.hint{display:block;text-align:center;color:#b18a72;font-size:23rpx;margin-top:20rpx}@keyframes fall{0%{transform:translateY(-70rpx);opacity:0}30%{opacity:1}100%{transform:translateY(180rpx);opacity:0}}@keyframes twinkle{50%{transform:scale(1.25);filter:brightness(1.4)}}
</style>


